import { getImage } from 'astro:assets';
import type { ImageMetadata } from 'astro';
import placeholder from '../assets/shot-placeholder.svg';
import { SHOT_CAPTURE, type ShotId, shotFiles } from '../data/shotCapture';
import { SHOTS, type ShotDef } from '../data/shots';

type Glob = Record<string, { default: ImageMetadata }>;

// Generated by `bun run screenshots` (or CI); nothing under screenshots/ except assets/ is committed.
const files: Glob = import.meta.glob('../../../screenshots/**/*.webp', { eager: true });

/** Placeholders stand in for missing images under `astro dev` or when CI could not capture a shot. */
const PLACEHOLDER_MODE = import.meta.env.DEV || process.env.KIRA_SITE_SHOTS === 'placeholder';

export interface ResolvedWindowShot extends ShotDef {
  readonly kind: 'window';
  readonly placeholder: boolean;
  readonly framed: string;
  readonly framedWidth: number;
  readonly framedHeight: number;
  /** 800 px wide WebP of the framed shot, for a tile or a phone at DPR 2. */
  readonly framedThumb: string;
  /** 1136 px wide WebP of the framed shot, for the `srcset` of narrow viewports. */
  readonly framedSmall: string;
  /** Build-time PNG of the framed shot for og:image; scrapers handle WebP unevenly. Not committed. */
  readonly social: string;
}

interface ResolvedCropShot extends ShotDef {
  readonly kind: 'floating' | 'region';
  readonly placeholder: boolean;
  readonly crop: string;
  readonly cropWidth: number;
  readonly cropHeight: number;
}

export type ResolvedShot = ResolvedWindowShot | ResolvedCropShot;

const warned = new Set<string>();

function find(file: string): ImageMetadata | undefined {
  const hit = Object.entries(files).find(([path]) => path.endsWith(`/screenshots/${file}`));
  if (hit) return hit[1].default;
  if (!PLACEHOLDER_MODE) throw new Error(`Missing screenshot ${file}. Run: bun run screenshots`);
  if (!warned.has(file)) {
    warned.add(file);
    console.warn(`Missing screenshot ${file}, using a placeholder. Run: bun run screenshots`);
  }
  return undefined;
}

/** Resolves one listed shot; throws at build time when a file is missing, unless placeholders are on. */
export async function resolveShot(id: string): Promise<ResolvedShot> {
  const def = SHOTS.find((s) => s.id === id);
  if (!def) throw new Error(`Unknown shot ${id}`);
  const capture = SHOT_CAPTURE[def.id];
  const { main } = shotFiles(def.id);
  const mainFound = find(main);
  const mainMeta = mainFound ?? placeholder;

  if (capture.kind !== 'window') {
    return {
      ...def,
      kind: capture.kind,
      placeholder: !mainFound,
      crop: mainMeta.src,
      cropWidth: mainMeta.width,
      cropHeight: mainMeta.height,
    };
  }
  const framedThumb = mainFound
    ? (await getImage({ src: mainFound, width: 800, format: 'webp' })).src
    : placeholder.src;
  const framedSmall = mainFound
    ? (await getImage({ src: mainFound, width: 1136, format: 'webp' })).src
    : placeholder.src;
  return {
    ...def,
    kind: 'window',
    placeholder: !mainFound,
    framed: mainMeta.src,
    framedWidth: mainMeta.width,
    framedHeight: mainMeta.height,
    framedThumb,
    framedSmall,
    social: mainFound ? (await getImage({ src: mainFound, format: 'png' })).src : placeholder.src,
  };
}

/** Fails the build when a listed shot has no file or the manifest and the site copy disagree. */
export async function resolveAllShots(): Promise<ResolvedShot[]> {
  const listed = new Set<string>(SHOTS.map((s) => s.id));
  for (const id of Object.keys(SHOT_CAPTURE) as ShotId[]) {
    if (!listed.has(id)) throw new Error(`Shot ${id} is in shotCapture.ts but has no SHOTS entry`);
  }
  for (const id of listed) {
    if (!(id in SHOT_CAPTURE)) throw new Error(`Shot ${id} is in SHOTS but not in shotCapture.ts`);
  }
  return Promise.all(SHOTS.map((s) => resolveShot(s.id)));
}
